<script setup>
import {onMounted,onUnmounted,ref} from 'vue'
const props=defineProps({project:Object,api:Function})
const cases=ref([]),runs=ref([]),documents=ref([]),docId=ref(''),chunks=ref([]),gold=ref([]),question=ref(''),notes=ref(''),answerable=ref(true),confirmed=ref(false),consent=ref(false),busy=ref(false),error=ref(''),trace=ref('')
let alive=true
async function load(){const data=await props.api('/projects/'+props.project.id+'/evaluation-cases?limit=200');const history=await props.api('/projects/'+props.project.id+'/evaluation-runs');const docs=await props.api('/projects/'+props.project.id+'/documents');if(alive){cases.value=data;runs.value=history;documents.value=docs.filter(d=>d.is_active&&d.current_version_id)}}
async function run(action){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){if(alive){error.value=e.message;trace.value=e.traceId||''}}finally{if(alive)busy.value=false}}
async function chooseDocument(){gold.value=[];chunks.value=[];if(!docId.value)return;const id=docId.value;await run(async()=>{const data=await props.api('/documents/'+id+'/chunks?limit=100');if(alive&&docId.value===id)chunks.value=data.items})}
function save(){return run(async()=>{await props.api('/projects/'+props.project.id+'/evaluation-cases',{method:'POST',body:JSON.stringify({question:question.value,answerable:answerable.value,gold_chunk_ids:answerable.value?gold.value:[],notes:notes.value,human_confirmed:confirmed.value})});question.value='';gold.value=[];notes.value='';confirmed.value=false;await load()})}
function evaluate(item){return run(async()=>{await props.api('/evaluation-cases/'+item.id+'/runs',{method:'POST',body:JSON.stringify({allow_external_processing:consent.value})});await load()})}
function exportRuns(){const url=URL.createObjectURL(new Blob([JSON.stringify({project_id:props.project.id,exported_at:new Date().toISOString(),runs:runs.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='retrieval-evaluation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const metric=v=>v===null||v===undefined?'不适用':Number(v).toFixed(3)
onMounted(()=>run(load));onUnmounted(()=>{alive=false})
</script>
<template>
  <div class="evaluation-center"><section class="panel"><div class="section-heading"><div><p class="eyebrow">RETRIEVAL EXPERIMENTS</p><h2>评测中心</h2></div><button class="ghost" :disabled="busy" @click="run(load)">刷新</button></div><p class="muted">对同一人工标注问题比较纯向量、混合检索、混合加重排。固定 Top-5 与候选20，保留模型配置和实际耗时。</p><p class="evaluation-notice">这里评估检索命中，不自动判定答案正确。样例必须人工核对；合成样例和AI草稿不能充当正式质量结论。正式评测仍需不少于30题的真实标注。</p><p v-if="error" class="error">{{ error }}<small>{{ trace }}</small></p>
    <form v-if="project.role==='admin'" class="case-form" @submit.prevent="save"><h3>建立标注样例</h3><label>问题<input v-model="question" maxlength="500" required placeholder="填写从资料中核对过的问题"></label><label>资料是否能够回答<select v-model="answerable" @change="gold=[]"><option :value="true">可回答：选择标准证据</option><option :value="false">不可回答：不设置标准片段</option></select></label><template v-if="answerable"><label>标准证据所在资料<select v-model="docId" @change="chooseDocument"><option value="">选择当前可用资料</option><option v-for="doc in documents" :key="doc.id" :value="doc.id">{{ doc.title }} · v{{ doc.current_version_number }}</option></select></label><p class="hint">每份资料展示前100个片段，本次可选择同一份资料中至多20个标准片段。</p><div class="gold-picker"><label v-for="chunk in chunks" :key="chunk.id"><input v-model="gold" type="checkbox" :value="chunk.id"><span><strong>片段 {{ chunk.ordinal+1 }} · {{ chunk.page?`第${chunk.page}页`:`第${chunk.line_start}—${chunk.line_end}行` }}</strong>{{ chunk.text }}</span></label></div></template><label>标注说明<textarea v-model="notes" maxlength="2000" rows="2" placeholder="资料来源、核对依据、合成样例声明等"></textarea></label><label class="center-checkbox"><input v-model="confirmed" type="checkbox">我已实际核对资料与标准证据（不勾选则保存为草稿，不能运行）</label><button class="primary" :disabled="busy||!question.trim()||(answerable&&!gold.length)">保存样例</button></form><p v-else class="hint">标注由项目管理员维护。成员可以运行已确认的样例，实验记录仅本人可见。</p>
  </section><section class="panel"><h2>样例与实验</h2><label class="center-checkbox"><input v-model="consent" type="checkbox">允许本次实验将问题及有效候选证据发送至向量和重排序服务；每个样例运行三个检索配置。</label><p v-if="!cases.length" class="center-empty">暂无样例，请先由管理员建立标注。</p><article v-for="item in cases" :key="item.id" class="eval-case"><div><strong>{{ item.question }}</strong><p>{{ !item.evidence_current?'标准证据已失效，请重新标注':item.human_confirmed?'已人工确认':'待人工确认草稿' }} · {{ item.answerable?'可回答':'不可回答' }} · 标准片段 {{ item.gold_chunk_ids.length }} 个</p><small>{{ item.notes }}</small></div><button class="ghost" :disabled="busy||!consent||!item.human_confirmed||!item.evidence_current" @click="evaluate(item)">{{ busy?'处理中…':'运行三组对比' }}</button></article></section>
  <section class="panel"><div class="section-heading"><h2>我的实验记录</h2><button class="ghost" :disabled="!runs.length" @click="exportRuns">导出JSON</button></div><p class="hint">最近20次；每次单题各模式的倒数排名不是整套数据集的MRR。不可回答题无正例，Recall与排名指标不适用，不等于已经验证拒答效果。</p><p v-if="!runs.length" class="center-empty">尚未运行实验。</p><article v-for="entry in runs" :key="entry.id" class="eval-run"><h3>{{ entry.snapshot.question }}</h3><p v-if="!entry.evidence_current" class="evaluation-notice">资料版本已变化，已隐藏失效实验结果，请重新运行。</p><template v-else><p class="hint">{{ new Date(entry.created_at).toLocaleString('zh-CN') }} · 向量 {{ entry.snapshot.embedding_model }} · 重排 {{ entry.snapshot.rerank_model }}</p><div class="table-wrap"><table class="center-table"><thead><tr><th>模式 / 状态</th><th>Recall@5</th><th>倒数排名</th><th>实际执行 / 耗时</th></tr></thead><tbody><tr v-for="result in entry.results" :key="result.mode"><td>{{ result.mode }}<small>{{ result.status }}</small></td><td>{{ metric(result.recall_at_5) }}</td><td>{{ metric(result.reciprocal_rank) }}</td><td>{{ result.effective_mode||'不可用' }}<small>重排 {{ result.rerank_status||'未执行' }} · {{ result.timings_ms?.total??'—' }} ms</small><small v-for="warning in result.warnings||[]" :key="warning.code">{{ warning.message }}</small></td></tr></tbody></table></div></template></article></section></div>
</template>
